-- 0006_bam_part1.sql — parte 1 de 7 del catálogo BAM 18.1.1.
-- Idempotente: puede repetirse sin duplicar datos.
-- Generado por scripts/split-migration.mjs — no editar a mano.
-- ─────────────────────────────────────────────────────────────
-- VORA — Catálogo BAM 18.1.1 + precios CDMX (catálogo completo)
-- Generado por scripts/import-bam-prices.mjs — no editar a mano.
-- Fuente: catalog-prices.db — Base de Alimentos de México (BAM)
-- 18.1.1, INSP/INCMNSZ 2019. Capa de precios: rangos de referencia
-- estimados CDMX al 2026-08-14 (SNIIM/Profeco/minoristas).
-- Política de precios: el precio vive en price_records (fechado por
-- ciudad/tienda/presentación); foods.price_mxn queda null. Additivo e
-- idempotente. Requiere 0001 (public.foods) y 0005 (public.price_records,
-- columnas de nutrición); puede reejecutarse sin duplicar datos.
-- ─────────────────────────────────────────────────────────────

-- Alimentos BAM: columnas del catálogo
alter table public.foods add column if not exists bam_code text;
alter table public.foods add column if not exists local_price_key text;
alter table public.foods add column if not exists preparation_state text;
alter table public.foods add column if not exists price_update_required boolean not null default false;
alter table public.foods add column if not exists nutrients jsonb;
alter table public.foods drop constraint if exists foods_source_check;
alter table public.foods add constraint foods_source_check check (source in ('seed', 'usda', 'user', 'bam'));

-- price_records: rangos de referencia (low/high/reference) y capa CDMX
alter table public.price_records add column if not exists price_mxn_low numeric check (price_mxn_low >= 0);
alter table public.price_records add column if not exists price_mxn_high numeric check (price_mxn_high >= 0);
alter table public.price_records add column if not exists price_mxn_reference numeric check (price_mxn_reference >= 0);
alter table public.price_records add column if not exists price_record_id text;
alter table public.price_records add column if not exists is_observed_item_price boolean not null default false;
alter table public.price_records add column if not exists needs_local_confirmation boolean not null default true;
alter table public.price_records drop constraint if exists price_records_price_type_check;
alter table public.price_records add constraint price_records_price_type_check
  check (price_type in ('retail', 'wholesale', 'promotional', 'user_entered', 'estimated', 'estimated_reference_range'));
alter table public.price_records drop constraint if exists price_records_confidence_check;
alter table public.price_records add constraint price_records_confidence_check
  check (confidence in ('high', 'medium', 'low', 'low_to_medium'));
create unique index if not exists price_records_food_observed_type_key
  on public.price_records (food_id, observed_at, price_type);

-- Alimentos BAM (source = 'bam'), 2045 filas.
on conflict (food_id) where food_id is not null do nothing;